// Pipboy Layout Component
export default function Layout({ children }: { children: React.ReactNode }) {
  const [location] = useLocation();
  const date = new Date();
  const [time, setTime] = useState(date.toLocaleTimeString());
  const [pipelineState, setPipelineState] = useState<PipelineState>("idle");

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date().toLocaleTimeString());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      try {
        const status = await getStatus();
        if (!cancelled) {
          setPipelineState(status.pipeline);
        }
      } catch {
        if (!cancelled) {
          setPipelineState("idle");
        }
      }
    };

    void load();
    const interval = window.setInterval(() => {
      void load();
    }, 1500);

    return () => {
      cancelled = true;
      window.clearInterval(interval);
    };
  }, []);

  const vfdState =
    pipelineState === "error"
      ? "error"
      : pipelineState === "running" || pipelineState === "paused" || pipelineState === "stopping"
        ? "running"
        : "idle";

  const statusClass = (slot: "idle" | "running" | "error") => {
    if (slot !== vfdState) {
      return "text-primary/25";
    }
    if (slot === "error") {
      return "text-red-400 drop-shadow-[0_0_6px_rgba(248,113,113,0.8)]";
    }
    return cn("text-primary glow-text", slot === "running" && "vfd-running");
  };

  return (
    <div className="h-screen bg-background text-primary font-mono relative overflow-hidden flex flex-col">
      {/* CRT Effects */}
      <div className="scanlines" />
      <div className="scanline-move" />
      
      {/* Top Bar */}
      <header className="border-b-2 border-primary/50 p-4 flex justify-between items-end relative z-10 bg-background/90 backdrop-blur-sm">
        <div className="flex gap-6 items-baseline">
          <h1 className="text-4xl font-display font-bold glow-text tracking-widest">PIP-MANAGER 3000</h1>
          <nav className="flex gap-4 text-lg">
            <Link
              href="/"
              className={cn(
                "flex items-center gap-2 hover:text-primary hover:glow-text transition-all uppercase",
                location === "/" && "text-primary glow-text underline decoration-2 underline-offset-4",
              )}
            >
              <House className="w-4 h-4" />
              HOME
            </Link>
            <Link
              href="/process/all/all"
              className={cn(
                "flex items-center gap-2 hover:text-primary hover:glow-text transition-all uppercase",
                location.startsWith("/process/") && "text-primary glow-text underline decoration-2 underline-offset-4",
              )}
            >
              <FolderOpen className="w-4 h-4" />
              FILES
            </Link>
            <Link
              href="/report"
              className={cn(
                "flex items-center gap-2 hover:text-primary hover:glow-text transition-all uppercase",
                location === "/report" && "text-primary glow-text underline decoration-2 underline-offset-4",
              )}
            >
              <ChartColumn className="w-4 h-4" />
              STATS
            </Link>
          </nav>
        </div>
        
        <div className="flex flex-col items-end">
          <div className="mb-1 flex items-center gap-3 text-[11px] font-mono uppercase tracking-[0.25em]">
            <span className={cn("transition-colors", statusClass("idle"))}>IDLE</span>
            <span className="text-primary/20">|</span>
            <span className={cn("transition-colors", statusClass("running"))}>RUNNING</span>
            <span className="text-primary/20">|</span>
            <span className={cn("transition-colors", statusClass("error"))}>ERROR</span>
          </div>
          <div className="flex items-start gap-4">
            <div className="pt-0.5">
              <SignatureMark />
            </div>
            <div className="flex flex-col items-end">
              <div className="text-xs text-primary/70 uppercase tracking-widest">Vault-Tec Ops</div>
              <div className="text-xl font-display">{time}</div>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 min-h-0 p-6 relative z-10 overflow-hidden">
        <div className="border-2 border-primary/30 h-full min-h-0 relative rounded-sm shadow-[0_0_15px_rgba(16,255,16,0.1)] bg-background/50">
           {/* Corner decors */}
           <div className="absolute -top-[2px] -left-[2px] w-4 h-4 border-t-2 border-l-2 border-primary"></div>
           <div className="absolute -top-[2px] -right-[2px] w-4 h-4 border-t-2 border-r-2 border-primary"></div>
           <div className="absolute -bottom-[2px] -left-[2px] w-4 h-4 border-b-2 border-l-2 border-primary"></div>
           <div className="absolute -bottom-[2px] -right-[2px] w-4 h-4 border-b-2 border-r-2 border-primary"></div>
           
           <div className="p-6 h-full min-h-0 overflow-y-auto overflow-x-hidden">
             {children}
           </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t-2 border-primary/50 p-2 px-6 flex justify-between text-xs text-primary/60 uppercase tracking-wider relative z-10 bg-background">
        <div className="flex gap-4">
          <span>HP: 100/100</span>
          <span>AP: 95/100</span>
          <span>RADS: 0</span>
        </div>
        <div>
          SYS.STATUS: ONLINE
        </div>
      </footer>
    </div>
  );
}
